    'eid_adha.faq_q2': '\u0627\u0633 \u0633\u0627\u0644 \u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u06a9\u0628 \u06c1\u06d2\u061f',
    'eid_adha.faq_a2': '{hyear} \u06c1\u062c\u0631\u06cc \u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u062a\u062e\u0645\u06cc\u0646\u06cc \u0637\u0648\u0631 \u067e\u0631 {date} \u06a9\u0648 \u0622\u062a\u06cc \u06c1\u06d2\u06d4',
