    'eid_adha.faq_a3': '{hyear} \u06c1\u062c\u0631\u06cc \u0630\u06cc \u0627\u0644\u062d\u062c \u06a9\u06d2 10\u0648\u06cc\u06ba \u062f\u0646 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u06c1\u06d2\u06d4',
    'eid_adha.faq_q4': '\u06a9\u06cc\u0627 \u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u06a9\u06cc \u062a\u0627\u0631\u06cc\u062e \u0645\u062e\u062a\u0644\u0641 \u0645\u0645\u0627\u0644\u06a9 \u0645\u06cc\u06ba \u0645\u062e\u062a\u0644\u0641 \u06c1\u0648 \u0633\u06a9\u062a\u06cc \u06c1\u06d2\u061f',
    'eid_adha.faq_a4': '\u062c\u06cc \u06c1\u0627\u06ba\u060c \u0645\u0642\u0627\u0645\u06cc \u0630\u06cc \u0627\u0644\u062d\u062c \u06c1\u0644\u0627\u0644 \u06a9\u06cc \u0631\u0624\u06cc\u062a \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0627\u06cc\u06a9 \u062f\u0646 \u0645\u062e\u062a\u0644\u0641 \u06c1\u0648 \u0633\u06a9\u062a\u06cc \u06c1\u06d2\u06d4',
    'eid_adha.faq_q5': '\u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u06a9\u0627 \u062d\u062c \u0633\u06d2 \u06a9\u06cc\u0627 \u062a\u0639\u0644\u0642 \u06c1\u06d2\u061f',
    'eid_adha.faq_a5': '\u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u06cc\u0648\u0645 \u0639\u0631\u0641\u06c1 \u06a9\u06d2 \u0628\u0639\u062f \u0622\u0646\u06d2 \u0648\u0627\u0644\u0627 \u06cc\u0648\u0645 \u0627\u0644\u0646\u062d\u0631 \u06c1\u06d2\u06d4 10 \u0630\u06cc \u0627\u0644\u062d\u062c \u06a9\u0648 \u062d\u062c\u0627\u062c \u0645\u0646\u06cc\u0670 \u0645\u06cc\u06ba \u0642\u0631\u0628\u0627\u0646\u06cc \u0627\u062f\u0627 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4',
    'eid_adha.faq_q6': '\u0642\u0631\u0628\u0627\u0646\u06cc \u06a9\u06cc\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0627\u0633 \u06a9\u0627 \u062d\u06a9\u0645 \u06a9\u06cc\u0627 \u06c1\u06d2\u061f',
    'eid_adha.faq_a6': '\u0642\u0631\u0628\u0627\u0646\u06cc \u0648\u06c1 \u062c\u0627\u0646\u0648\u0631 \u06c1\u06d2 \u062c\u0648 \u0627\u0644\u0644\u06c1 \u06a9\u06cc \u0631\u0636\u0627 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0639\u06cc\u062f \u06a9\u06d2 \u062f\u0646\u0648\u06ba \u0645\u06cc\u06ba \u0630\u0628\u062d \u06a9\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4 \u062c\u0645\u06c1\u0648\u0631 \u0641\u0642\u06c1\u0627\u0621 \u06a9\u06d2 \u0646\u0632\u062f\u06cc\u06a9 \u0627\u0633\u062a\u0637\u0627\u0639\u062a \u0631\u06a9\u06be\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0644\u06cc\u06d2 \u0633\u0646\u062a \u0645\u0624\u06a9\u062f\u06c1 \u06c1\u06d2\u06d4',
    'eid_adha.faq_q7': '\u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u06a9\u062a\u0646\u06d2 \u062f\u0646 \u0686\u0644\u062a\u06cc \u06c1\u06d2\u061f',
