    'eid_adha.faq_q9': '\u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u06a9\u06d2 \u0627\u06c1\u0645 \u0627\u0631\u06a9\u0627\u0646 \u06a9\u06cc\u0627 \u06c1\u06cc\u06ba\u061f',
    'eid_adha.faq_a9': '\u0646\u0645\u0627\u0632 \u0639\u06cc\u062f\u060c \u062a\u06a9\u0628\u06cc\u0631\u060c \u0642\u0631\u0628\u0627\u0646\u06cc\u060c \u0631\u0634\u062a\u06c1 \u062f\u0627\u0631\u0648\u06ba \u0633\u06d2 \u0645\u0644\u0627\u0642\u0627\u062a \u0627\u0648\u0631 \u0645\u0628\u0627\u0631\u06a9\u0628\u0627\u062f\u06cc \u06a9\u0627 \u062a\u0628\u0627\u062f\u0644\u06c1\u06d4',
