    'eid_adha.faq_a10': '\u06a9\u06cc\u0648\u0646\u06a9\u06c1 \u06c1\u062c\u0631\u06cc \u0642\u0645\u0631\u06cc \u0633\u0627\u0644 \u0639\u06cc\u0633\u0648\u06cc \u0633\u0627\u0644 \u0633\u06d2 \u062a\u0642\u0631\u06cc\u0628\u0627\u064b 10-11 \u062f\u0646 \u0686\u06be\u0648\u0679\u0627 \u06c1\u06d2\u060c \u0644\u06c1\u0630\u0627 \u0639\u06cc\u062f \u06c1\u0631 \u0633\u0627\u0644 \u0627\u062a\u0646\u06cc \u06c1\u06cc \u0645\u0642\u062f\u0627\u0631 \u0633\u06d2 \u0622\u06af\u06d2 \u0628\u0691\u06be\u062a\u06cc \u06c1\u06d2\u06d4',
    'eid_adha.info_title': '\ud83d\udcd6 \u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba',
