    'eid_adha.info_h1_body': '\u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u0627\u0633\u0644\u0627\u0645 \u06a9\u06cc \u062f\u0648 \u0639\u06cc\u062f\u0648\u06ba \u0645\u06cc\u06ba \u0633\u06d2 \u0628\u0691\u06cc \u0639\u06cc\u062f \u06c1\u06d2\u060c \u062c\u0648 \u06cc\u0648\u0645 \u0639\u0631\u0641\u06c1 \u06a9\u06d2 \u0628\u0639\u062f 10 \u0630\u06cc \u0627\u0644\u062d\u062c \u06a9\u0648 \u0622\u062a\u06cc \u06c1\u06d2\u06d4 \u0627\u0633\u06d2 \u06cc\u0648\u0645 \u0627\u0644\u0646\u062d\u0631 \u06a9\u06c1\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u060c \u062c\u0628 \u0645\u0633\u0644\u0645\u0627\u0646 \u062d\u0636\u0631\u062a \u0627\u0628\u0631\u0627\u06c1\u06cc\u0645 \u0639\u0644\u06cc\u06c1 \u0627\u0644\u0633\u0644\u0627\u0645 \u06a9\u06cc \u0633\u0646\u062a \u06a9\u0648 \u0632\u0646\u062f\u06c1 \u0631\u06a9\u06be\u062a\u06d2 \u06c1\u0648\u0626\u06d2 \u0642\u0631\u0628\u0627\u0646\u06cc \u067e\u06cc\u0634 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4',
    'eid_adha.info_h2': '\u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u06a9\u06cc\u0633\u06d2 \u062b\u0627\u0628\u062a \u06c1\u0648\u062a\u06cc \u06c1\u06d2',
    'eid_adha.info_h2_body': '\u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u0630\u06cc \u0627\u0644\u062d\u062c \u06a9\u06d2 \u0622\u063a\u0627\u0632 \u06a9\u06cc \u06c1\u0644\u0627\u0644 \u06a9\u06cc \u0631\u0624\u06cc\u062a \u0633\u06d2 \u062b\u0627\u0628\u062a \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u060c \u067e\u06be\u0631 \u0627\u0633 \u06a9\u0627 10\u0648\u0627\u06ba \u062f\u0646 \u0634\u0645\u0627\u0631 \u06a9\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4 \u062a\u0627\u0631\u06cc\u062e \u0645\u0645\u0627\u0644\u06a9 \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646 \u0631\u0624\u06cc\u062a \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0627\u06cc\u06a9 \u062f\u0646 \u0645\u062e\u062a\u0644\u0641 \u06c1\u0648 \u0633\u06a9\u062a\u06cc \u06c1\u06d2\u06d4',
    'eid_adha.info_h3': '\u06c1\u0631 \u0639\u06cc\u0633\u0648\u06cc \u0633\u0627\u0644 \u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u06a9\u06cc\u0648\u06ba \u0622\u06af\u06d2 \u0628\u0691\u06be\u062a\u06cc \u06c1\u06d2',
    'eid_adha.info_h3_body': '\u06c1\u062c\u0631\u06cc \u0642\u0645\u0631\u06cc \u0633\u0627\u0644 \u0639\u06cc\u0633\u0648\u06cc \u0633\u0627\u0644 \u0633\u06d2 \u062a\u0642\u0631\u06cc\u0628\u0627\u064b 10-11 \u062f\u0646 \u0686\u06be\u0648\u0679\u0627 \u06c1\u06d2\u060c \u0627\u0633 \u0644\u06cc\u06d2 \u0639\u064a\u062f \u0627\u0644\u0627\u0636\u062d\u06cc\u0670 \u06c1\u0631 \u0633\u0627\u0644 \u0627\u062a\u0646\u06cc \u06c1\u06cc \u0645\u0642\u062f\u0627\u0631 \u0633\u06d2 \u0622\u06af\u06d2 \u0628\u0691\u06be\u062a\u06cc \u06c1\u06d2 \u0627\u0648\u0631 \u062a\u0642\u0631\u06cc\u0628\u0627\u064b 33 \u0633\u0627\u0644\u0648\u06ba \u0645\u06cc\u06ba \u062a\u0645\u0627\u0645 \u0645\u0648\u0633\u0645\u0648\u06ba \u0645\u06cc\u06ba \u06af\u06be\u0648\u0645\u062a\u06cc \u06c1\u06d2\u06d4',
    'eid_adha.links_title': '\ud83d\udd17 \u0645\u062a\u0639\u0644\u0642\u06c1 \u0631\u0648\u0627\u0628\u0637',
    'eid_adha.link_ramadan': '\ud83d\udd4b \u0631\u0645\u0636\u0627\u0646 \u0645\u06cc\u06ba \u06a9\u062a\u0646\u06d2 \u062f\u0646 \u0628\u0627\u0642\u06cc',
    'eid_adha.link_fitr': '\ud83c\udf19 \u0639\u06cc\u062f \u0627\u0644\u0641\u0637\u0631 \u0645\u06cc\u06ba \u06a9\u062a\u0646\u06d2 \u062f\u0646 \u0628\u0627\u0642\u06cc',
