    'eid_adha.faq_q8': '\u0986\u09b0\u09be\u09ab\u09be \u09a6\u09bf\u09a8\u09c7\u09b0 \u0996\u09be\u09b8\u09bf\u09af\u09bc\u09a4 \u0995\u09c0?',
