    'eid_adha.faq_q9': '\u0989\u09a6\u09c1\u09b2 \u0986\u09af\u09bc\u09b9\u09be\u09b0 \u09aa\u09cd\u09b0\u09a7\u09be\u09a8 \u0987\u09ac\u09be\u09a6\u09a4\u0997\u09c1\u09b2\u09bf \u0995\u09c0?',
    'eid_adha.faq_a9': '\u0989\u09a6\u09c1\u09b2 \u09a8\u09be\u09ae\u09be\u099c, \u09a4\u09be\u0995\u09ac\u09bf\u09b0, \u0995\u09cb\u09b0\u09ac\u09be\u09a8\u09bf (\u0989\u09a6\u09cd\u09a7\u09bf\u09df\u09be), \u0986\u09a4\u09cd\u09ae\u09c0\u09af\u09bc\u09a6\u09c7\u09b0 \u09a6\u09c7\u0996\u09be \u098f\u09ac\u0982 \u09b6\u09c1\u09ad\u09c7\u099a\u09cd\u099b\u09be \u09ac\u09bf\u09a8\u09bf\u09ae\u09af\u09bc\u0964',
    'eid_adha.faq_q10': '\u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u0997\u09cd\u09b0\u09c7\u0997\u09cb\u09b0\u09bf\u09af\u09bc\u09be\u09a8 \u09ac\u099b\u09b0\u09c7 \u0989\u09a6\u09c1\u09b2 \u0986\u09af\u09bc\u09b9\u09be\u09b0 \u09a4\u09be\u09b0\u09bf\u0996 \u0995\u09c7\u09a8 \u09aa\u09b0\u09bf\u09ac\u09b0\u09cd\u09a4\u09a8 \u09b9\u09af\u09bc?',
    'eid_adha.faq_a10': '\u0995\u09be\u09b0\u09a3 \u09b9\u09bf\u099c\u09b0\u09bf \u099a\u09be\u09a8\u09cd\u09a6\u09cd\u09b0 \u09ac\u099b\u09b0 \u0997\u09cd\u09b0\u09c7\u0997\u09cb\u09b0\u09bf\u09af\u09bc\u09be\u09a8 \u09ac\u099b\u09b0\u09c7\u09b0 \u099a\u09c7\u09af\u09bc\u09c7 \u09aa\u09cd\u09b0\u09be\u09af\u09bc \u09e7\u09e6\u2013\u09e7\u09e7 \u09a6\u09bf\u09a8 \u099b\u09cb\u099f, \u0989\u09a6\u09c1\u09b2 \u09aa\u09cd\u09b0\u09a4\u09bf \u09ac\u099b\u09b0 \u098f\u0995\u0987 \u09aa\u09b0\u09bf\u09ae\u09be\u09a3 \u098f\u0997\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u09af\u09bc\u0964',
    'eid_adha.info_title': '\ud83d\udcd6 \u0989\u09a6\u09c1\u09b2 \u0986\u09af\u09bc\u09b9\u09be \u09b8\u09ae\u09cd\u09aa\u09b0\u09cd\u0995\u09c7',
    'eid_adha.info_h1': '\u0989\u09a6\u09c1\u09b2 \u0986\u09af\u09bc\u09b9\u09be \u0995\u09c0',
    'eid_adha.info_h1_body': '\u0989\u09a6\u09c1\u09b2 \u0986\u09af\u09bc\u09b9\u09be \u0987\u09b8\u09b2\u09be\u09ae\u09c7\u09b0 \u09a6\u09c1\u099f\u09bf \u0989\u09a6\u09c1\u09b2\u09c7\u09b0 \u09ae\u09a7\u09cd\u09af\u09c7 \u09ac\u09dc, \u09af\u09be \u0986\u09b0\u09be\u09ab\u09be\u09b0 \u09aa\u09b0 \u09e7\u09e6 \u099c\u09bf\u09b2\u09b9\u099c\u09c7 \u0986\u09b8\u09c7\u0964 \u098f\u099f\u09bf \u0987\u09df\u09be\u0989\u09ae\u09c1\u09a8 \u09a8\u09b9\u09b0 \u09a8\u09be\u09ae\u09c7 \u09aa\u09b0\u09bf\u099a\u09bf\u09a4, \u09af\u0996\u09a8 \u09ae\u09c1\u09b8\u09b2\u09bf\u09ae\u09b0\u09be \u09a8\u09ac\u09c0 \u0987\u09ac\u09cd\u09b0\u09be\u09b9\u09bf\u09ae (\u0986.) \u098f\u09b0 \u09b8\u09c1\u09a8\u09cd\u09a8\u09be\u09a4 \u0985\u09a8\u09c1\u09b8\u09b0\u09a3\u09c7 \u0995\u09cb\u09b0\u09ac\u09be\u09a8\u09bf \u0995\u09b0\u09c7\u0964',
    'eid_adha.info_h2': '\u0989\u09a6\u09c1\u09b2 \u0986\u09af\u09bc\u09b9\u09be \u0995\u09c0\u09ad\u09be\u09ac\u09c7 \u09a8\u09bf\u09b6\u09cd\u099a\u09bf\u09a4 \u09b9\u09af\u09bc',
    'eid_adha.info_h2_body': '\u0989\u09a6\u09c1\u09b2 \u0986\u09af\u09bc\u09b9\u09be \u099c\u09bf\u09b2\u09b9\u099c\u09c7\u09b0 \u09b9\u09bf\u09b2\u09be\u09b2 \u09a6\u09c7\u0996\u09be\u09b0 \u099c\u09b0\u09bf\u09df\u09c7 \u0986\u09b0\u09ae\u09cd\u09ad \u09a8\u09bf\u09b6\u09cd\u099a\u09bf\u09a4 \u0995\u09b0\u09c7, \u09a4\u09be\u09b0\u09aa\u09b0 \u09e7\u09e6\u09a4\u09ae \u09a6\u09bf\u09a8 \u0997\u09a3\u09a8\u09be \u0995\u09b0\u09be \u09b9\u09af\u09bc\u0964 \u09a4\u09be\u09b0\u09bf\u0996 \u09a6\u09c7\u09b6\u09ad\u09c7\u09a6\u09c7 \u09b0\u09c2\u09df\u09a4 \u0985\u09a8\u09c1\u09af\u09be\u09df\u09c0 \u098f\u0995\u09a6\u09bf\u09a8 \u09ad\u09bf\u09a8\u09cd\u09a8 \u09b9\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u0964',
    'eid_adha.info_h3': '\u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u0997\u09cd\u09b0\u09c7\u0997\u09cb\u09b0\u09bf\u09af\u09bc\u09be\u09a8 \u09ac\u099b\u09b0\u09c7 \u0989\u09a6\u09c1\u09b2 \u0986\u09af\u09bc\u09b9\u09be \u0995\u09c7\u09a8 \u098f\u0997\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u09af\u09bc',
    'eid_adha.info_h3_body': '\u09b9\u09bf\u099c\u09b0\u09bf \u099a\u09be\u09a8\u09cd\u09a6\u09cd\u09b0 \u09ac\u099b\u09b0 \u0997\u09cd\u09b0\u09c7\u0997\u09cb\u09b0\u09bf\u09af\u09bc\u09be\u09a8 \u09ac\u099b\u09b0\u09c7\u09b0 \u099a\u09c7\u09af\u09bc\u09c7 \u09aa\u09cd\u09b0\u09be\u09af\u09bc \u09e7\u09e6\u2013\u09e7\u09e7 \u09a6\u09bf\u09a8 \u099b\u09cb\u099f, \u09a4\u09be\u0987 \u0989\u09a6\u09c1\u09b2 \u0986\u09af\u09bc\u09b9\u09be \u09aa\u09cd\u09b0\u09a4\u09bf \u09ac\u099b\u09b0 \u098f\u0995\u0987 \u09aa\u09b0\u09bf\u09ae\u09be\u09a3 \u098f\u0997\u09bf\u09af\u09bc\u09c7 \u09af\u09be\u09af\u09bc\u0964',
    'eid_adha.links_title': '\ud83d\udd17 \u09b8\u09ae\u09cd\u09aa\u09b0\u09cd\u0995\u09bf\u09a4 \u09b2\u09bf\u0999\u09cd\u0995',
    'eid_adha.link_ramadan': '\ud83d\udd4b \u09b0\u09ae\u099c\u09be\u09a8 \u0986\u09b8\u09a4\u09c7 \u0995\u09a4\u09a6\u09bf\u09a8 \u09ac\u09be\u0995\u09bf',
    'eid_adha.link_fitr': '\ud83c\udf19 \u0989\u09a6\u09c1\u09b2 \u09ab\u09bf\u09a4\u09b0 \u0986\u09b8\u09a4\u09c7 \u0995\u09a4\u09a6\u09bf\u09a8 \u09ac\u09be\u0995\u09bf',
    'eid_adha.link_new_year': '\ud83d\udcc5 \u09a8\u09a4\u09c1\u09a8 \u09b9\u09bf\u099c\u09b0\u09bf \u09ac\u099b\u09b0 \u0986\u09b8\u09a4\u09c7 \u0995\u09a4\u09a6\u09bf\u09a8 \u09ac\u09be\u0995\u09bf',
    'eid_adha.link_moon': '\ud83c\udf19 \u0986\u099c\u0995\u09c7\u09b0 \u099a\u09be\u0981\u09a6\u09c7\u09b0 \u0985\u09ac\u09b8\u09cd\u09a5\u09be',
    'eid_adha.link_hijri_today': '\ud83d\udcc5 \u0986\u099c\u0995\u09c7\u09b0 \u09b9\u09bf\u099c\u09b0\u09bf \u09a4\u09be\u09b0\u09bf\u0996',
